  if(/\b(mean|average|median|mode|range|standard deviation|deviation|\bsd\b|iqr|interquartile|statistics|stats)\b/.test(t)&&(t.match(/-?\d+(\.\d+)?/g)||[]).length>=2){try{r=A.stats(t)}catch(e){}if(r)return r}
  if(/\b(gcf|gcd|hcf|greatest common|highest common|lcm|least common|lowest common|common denominator|prime|factori[sz]ation|factors of|divisors of)\b/.test(t)&&!/[a-z]\s*\^|x/.test(t.replace(/\b(prime|factors?|factori[sz]ation|of|is|the|gcf|gcd|lcm|hcf|and|divisors|greatest|common|least|lowest|highest|denominator|what|find|a|an)\b/g,""))){try{r=A.numberFacts(t)}catch(e){}if(r)return r}
  if(/\b(to|in|into)\b/.test(t)&&/\d/.test(t)){try{r=A.convert(t)}catch(e){}if(r)return r;try{r=A.trig(t)}catch(e){}if(r)return r}
  if(/\b(sin|cos|tan)\b/.test(t)&&!/=/.test(t)){try{r=A.trig(t)}catch(e){}if(r)return r}
  if(/\b(area|volume|circumference|perimeter|hypotenuse|pythag|legs?|radius|diameter|cylinder|cone|sphere|triangle|rectangle|square|cube|box|polygon|hexagon|pentagon|octagon|interior|arc|sector)\b/.test(t)&&!/[a-z]\s*[\^²=]/.test(t.replace(/\b(area|volume|of|a|an|the|with|radius|diameter|height|base|r|h|d)\b/g,""))){try{r=A.geometry(t)}catch(e){}if(r)return r}
  /* equations & expressions */
  var want=(t.match(/\bfor\s+([a-z])\b/)||[])[1],cmd=(t.match(/\b(factor|factori[sz]e|expand|simplify|graph|vertex|analy[sz]e|evaluate|solve)\b/)||[])[1];
  var body=src.replace(/\bfor\s+[a-zA-Z]\b\s*:?/,"").replace(CMD,"").replace(/^(the\s+)?(equation|expression|inequality|system)\s*/i,"");want=want&&(src.match(new RegExp("\\bfor\\s+("+want+")\\b","i"))||[])[1]||want;
  var ifm=body.match(/(?:when|if|where|at)\s+([a-z])\s*=\s*(-?[\d.\/]+)\s*\??$/);
