  if(/\b(thank|thanks|thx|ty|cheers|rahmat|great job|good job|you'?re (the best|great|awesome|smart))\b/.test(t))return {html:"<p>"+L(rnd(["Any time! That's what I'm here for. 💜","You're welcome! Keep going — you're doing great.","Happy to help! Want another question to lock it in?"]),"Всегда пожалуйста! 💜")+"</p>",mood:"cheer"};
  if(/\b(who are you|what are you|your name|are you (an? )?(ai|robot|human|real|chatgpt|claude))\b/.test(t))return {html:"<p>"+L("I'm Axilotti, AXIOM's axolotl study buddy. I've read every lesson, Copybook note and formula in AXIOM, I solve maths step by step with exact arithmetic, and I learn what you find hard from your practice. I answer through the cloud when you're online, and I keep working right here on your device when you're offline.","Я Аксилотти, аксолотль-помощник AXIOM. Я знаю все уроки, конспекты и формулы, решаю задачи по шагам и запоминаю, что тебе трудно. Онлайн я отвечаю через облако, а без интернета продолжаю работать прямо на устройстве.")+"</p>",mood:"happy"};
