  if(/\bhow are you\b|\bhow'?s it going\b/.test(t))return {html:"<p>"+L("I'm splendid — my gills are fluffy and my equations are balanced. How's studying going?","Отлично — жабры пушистые, уравнения сбалансированы. Как учёба?")+"</p>",mood:"happy"};
  if(/\b(joke|funny|make me laugh)\b/.test(t))return {html:"<p>😄 "+esc(rnd(JOKES))+"</p>",mood:"cheer",chips:[chip(L("Another joke","Ещё шутку"),"tell me a joke"),chip(L("Fun maths fact","Интересный факт"),"fun fact")]};
